/* eslint-disable @typescript-eslint/no-unused-vars */
"use client";

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import {
  Sun,
  Moon,
  Menu,
  X,
  ChevronDown,
  Server,
  Cloud,
  Compass as Wordpress,
  Database,
  Zap,
  Building2,
  Shield,
  Phone,
  FileText,
  Briefcase,
  HardDrive,
  Monitor,
} from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import type { NavItem } from "@/types/nav";
import Link from "next/link";
import { useTheme } from "next-themes";
import Image from "next/image";
import { ScrollArea, ScrollBar } from "../ui/scroll-area";
import Dropdown from "../ui/menu-dropdown";

const navItems: NavItem[] = [
  { label: "Pricing", href: "/pricing" },
  {
    label: "Hosting",
    href: "/hosting",
    hasDropdown: true,
    dropdownItems: [
      {
        label: "Web Hosting",
        href: "/hosting/web-hosting",
        icon: Server,
        description: "NVMe SSD server",
      },
      {
        label: "Cloud Hosting",
        href: "/hosting/cloud-hosting",
        icon: Cloud,
        description: "Fast autoscaling server",
      },
      {
        label: "WordPress Hosting",
        href: "/hosting/wordpress-hosting",
        icon: Wordpress,
        description: "Fully Managed WordPress",
      },
      {
        label: "Reseller Hosting",
        href: "/hosting/reseller-hosting",
        icon: Building2,
        description: "Start your Business",
      },
      {
        label: "BDIX Hosting",
        href: "/hosting/bdix-hosting",
        icon: Database,
        description: "Lowest Network Latency",
      },
      {
        label: "Turbo Hosting",
        href: "/hosting/turbo-hosting",
        icon: Zap,
        description: "Fast Speed Guaranteed",
      },
    ],
  },
  { label: "Domain", href: "/domain" },
  {
    label: "Server",
    href: "/server",
    hasDropdown: true,
    dropdownItems: [
      {
        label: "VPS",
        href: "/server/vps",
        icon: HardDrive,
        description: "Virtual Private Server",
      },
      {
        label: "Dedicated",
        href: "/server/dedicated",
        icon: Monitor,
        description: "Dedicated Server Solutions",
      },
    ],
  },
  {
    label: "About",
    href: "/about",
    hasDropdown: true,
    dropdownItems: [
      {
        label: "Privacy Policy",
        href: "/privacy-policy",
        icon: Shield,
      },
      {
        label: "Terms & Condition",
        href: "/terms-conditions",
        icon: FileText,
      },
      {
        label: "Careers",
        href: "/about/careers",
        icon: Briefcase,
        badge: "(Hiring)",
      },
      {
        label: "Contact",
        href: "/contact",
        icon: Phone,
      },
    ],
  },
];

export function Navbar() {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const { theme, setTheme } = useTheme();
  const defaultLogo =
    "https://res.cloudinary.com/daspo1tk3/image/upload/v1757498973/logo11_nfcmpq.webp";

  const whiteLogo =
    "https://res.cloudinary.com/daspo1tk3/image/upload/v1757579469/footer-logo_z7x8v3.webp";

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 10);
    };
    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  return (
    <nav
      className="fixed top-0 left-0 right-0 z-50 transition-all duration-300 
        bg-white/95 dark:bg-gray-900/95 backdrop-blur-md shadow-sm"
    >
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16">
          {/* Logo */}
          <div className="flex-shrink-0">
            <Link href="/" className="flex items-center">
              <Image
                src={theme === "dark" ? whiteLogo : defaultLogo}
                alt="Hostnin Logo"
                width={140}
                height={80}
                quality={90}
                className="h-10 w-full object-contain"
                priority
              />
            </Link>
          </div>

          <div className="flex items-center gap-2">
            {/* Desktop Navigation */}
            <div className="hidden lg:flex items-center gap-2">
              {navItems.map((item) => (
                <div key={item.label} className="relative group">
                  <Link
                    href={item.href}
                    className="text-gray-700 dark:text-gray-300 hover:text-blue-600 dark:hover:text-blue-400 px-3 py-2 text-sm font-medium transition-colors duration-200 flex items-center gap-1"
                  >
                    {item.label}
                    {item.hasDropdown && (
                      <ChevronDown className="w-4 h-4 transition-transform group-hover:rotate-180" />
                    )}
                  </Link>
                  {item.hasDropdown && item.dropdownItems && (
                    <div
                      className={`absolute left-0 mt-2 bg-white dark:bg-gray-900 rounded-lg shadow-xl border border-gray-200 dark:border-gray-700 opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all duration-300 transform translate-y-2 group-hover:translate-y-0
                      ${item.label === "Hosting" ? "w-[550px]" : "w-56"}`}
                    >
                      <div
                        className={`grid gap-2 ${
                          item.label === "Hosting"
                            ? "grid-cols-1 sm:grid-cols-1 md:grid-cols-2"
                            : "grid-cols-1"
                        } p-2`}
                      >
                        {item.dropdownItems.map((dropdownItem) => {
                          const IconComponent = dropdownItem.icon;
                          return (
                            <Link
                              key={dropdownItem.label}
                              href={dropdownItem.href}
                              className="flex items-center gap-3 p-3 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-800 transition-colors group/item"
                            >
                              {IconComponent && (
                                <div className="flex-shrink-0 w-7 h-7 rounded-lg flex items-center justify-center">
                                  <IconComponent className="w-full h-full text-gray-900 dark:text-gray-200" />
                                </div>
                              )}
                              <div className="flex-1">
                                <div className="flex items-center gap-2">
                                  <span className="font-medium text-gray-900 dark:text-gray-100 group-hover/item:text-blue-600 dark:group-hover/item:text-blue-400">
                                    {dropdownItem.label}
                                  </span>
                                  {dropdownItem.badge && (
                                    <span className="text-xs bg-orange-100 dark:bg-orange-900/30 text-orange-600 dark:text-orange-400 px-2 py-1 rounded-full font-medium">
                                      {dropdownItem.badge}
                                    </span>
                                  )}
                                </div>
                                {dropdownItem.description && (
                                  <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
                                    {dropdownItem.description}
                                  </p>
                                )}
                              </div>
                            </Link>
                          );
                        })}
                      </div>
                    </div>
                  )}
                </div>
              ))}
            </div>

            <div className="flex items-center gap-2">
              {/* Theme Toggle */}
              <Button
                variant={"ghost"}
                onClick={() => setTheme(theme === "dark" ? "light" : "dark")}
                className="p-2 rounded hover:bg-gray-200 cursor-pointer dark:hover:bg-gray-700 transition-colors"
              >
                {theme === "dark" ? (
                  <Sun className="w-5 h-5" />
                ) : (
                  <Moon className="w-5 h-5" />
                )}
              </Button>

              {/* CTA Button */}
              <div className="hidden lg:block">
                <Dropdown />
              </div>
            </div>

            {/* Mobile menu button */}
            <div className="lg:hidden">
              <button
                onClick={() => setIsOpen(!isOpen)}
                className="text-gray-700 dark:text-gray-300 hover:text-blue-600 p-2"
              >
                {isOpen ? (
                  <X className="w-6 h-6" />
                ) : (
                  <Menu className="w-6 h-6" />
                )}
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Mobile Navigation */}
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0, height: 0 }}
            className="lg:hidden bg-white dark:bg-gray-900 border-t border-gray-200 dark:border-gray-700"
          >
            <ScrollArea className="h-[90vh] py-4">
              <div className="px-4 pt-4 pb-6 space-y-4">
                {navItems.map((item) => (
                  <div key={item.label}>
                    <Link
                      href={item.href}
                      className="text-gray-700 dark:text-gray-300 hover:text-blue-600 dark:hover:text-blue-400 block px-3 py-2 text-base font-medium"
                      onClick={() => setIsOpen(false)}
                    >
                      {item.label}
                    </Link>
                    {item.hasDropdown && item.dropdownItems && (
                      <div className="pl-6 space-y-1">
                        {item.dropdownItems.map((dropdownItem) => {
                          const IconComponent = dropdownItem.icon;
                          return (
                            <Link
                              key={dropdownItem.label}
                              href={dropdownItem.href}
                              className="flex items-center gap-2 px-3 py-2 text-sm text-gray-600 dark:text-gray-400 hover:text-blue-600 dark:hover:text-blue-400"
                              onClick={() => setIsOpen(false)}
                            >
                              {IconComponent && (
                                <IconComponent className="w-4 h-4" />
                              )}
                              <span>{dropdownItem.label}</span>
                              {dropdownItem.badge && (
                                <span className="text-xs bg-orange-100 dark:bg-orange-900/30 text-orange-600 dark:text-orange-400 px-1.5 py-0.5 rounded">
                                  {dropdownItem.badge}
                                </span>
                              )}
                            </Link>
                          );
                        })}
                      </div>
                    )}
                  </div>
                ))}

                <div className="w-full">
                  <Dropdown />
                </div>
              </div>
              <ScrollBar orientation="vertical" />
            </ScrollArea>
          </motion.div>
        )}
      </AnimatePresence>
    </nav>
  );
}
